  el.innerHTML = `<div class="qk-row">${pages.map((tb) => `<button type="button" class="qk-chip" data-quick="${esc(tb)}" title="${esc(navLabel(tb))}">${quickIconHtml(tb)}<span>${esc(quickShortName(tb))}</span></button>`).join("")}<button type="button" class="qk-chip qk-ed" data-quickedit aria-label="${esc(t("qk_edit"))}" title="${esc(t("qk_edit"))}">${pages.length ? "&#9998;" : `&#9998; ${esc(t("qk_edit"))}`}</button></div>`;
