    name: (NAV_GROUP_LABELS[g.dataset.group] && (NAV_GROUP_LABELS[g.dataset.group][LANG] || NAV_GROUP_LABELS[g.dataset.group].en)) || ((g.querySelector(".topnav-group-btn") || {}).textContent || "").replace(/\u25BC/g, "").trim(),
    tabs: [...g.querySelectorAll("[data-tab]")].map((b) => b.dataset.tab).filter((tb, i, a) => tb !== "overview" && a.indexOf(tb) === i),
