// The hero star: six rounded teal petals (the game's look), thin lines
// between them. filledSegs = how many petals are lit (6 = whole star).
// With starIndex, each petal is tappable (data-starseg "star|petal").
function heroStarSvg(filledSegs, opts = {}) {
  const c = 16, rOut = 13.5, rIn = 6.2, size = opts.size || 32;
  // Fill order goes counter-clockwise from the top:
  // 1 top, 2 upper-left, 3 lower-left, 4 bottom, 5 lower-right, 6 upper-right.
  const TIP_ANGLES = [-90, -150, 150, 90, 30, -30];
  const pt = (p) => `${p[0].toFixed(2)},${p[1].toFixed(2)}`;
  const petals = TIP_ANGLES.map((deg, i) => {
    const a = deg * Math.PI / 180, aL = (deg - 30) * Math.PI / 180, aR = (deg + 30) * Math.PI / 180;
    const tip = [c + rOut * Math.cos(a), c + rOut * Math.sin(a)];
    const l = [c + rIn * Math.cos(aL), c + rIn * Math.sin(aL)];
    const r = [c + rIn * Math.cos(aR), c + rIn * Math.sin(aR)];
    // Curve each side outwards a little so the petal is rounded.
    const q1 = [l[0] + (tip[0] - l[0]) * 0.55 + Math.cos(aL) * 1.6, l[1] + (tip[1] - l[1]) * 0.55 + Math.sin(aL) * 1.6];
    const q2 = [r[0] + (tip[0] - r[0]) * 0.55 + Math.cos(aR) * 1.6, r[1] + (tip[1] - r[1]) * 0.55 + Math.sin(aR) * 1.6];
    const tap = opts.starIndex != null ? ` data-starseg="${opts.starIndex}|${i + 1}" style="cursor:pointer; stroke:var(--panel);"` : ` style="stroke:var(--panel);"`;
    const title = opts.starIndex != null ? `<title>${opts.starIndex}\u2605 \u2014 shard ${i + 1}/6</title>` : "";
    return `<path${tap} d="M${c},${c} L${pt(l)} Q${pt(q1)} ${pt(tip)} Q${pt(q2)} ${pt(r)} Z" fill="${i < filledSegs ? "#25c2ca" : "#2b3348"}" stroke-width="0.7" stroke-linejoin="round">${title}</path>`;
  });
  return `<svg viewBox="0 0 32 32" width="${size}" height="${size}" style="display:block;">${petals.join("")}<circle cx="${c}" cy="${c}" r="1.3" style="fill:var(--panel);" pointer-events="none" /></svg>`;
}
// The Dashboard's reference reads that need nothing from the site settings
// (no "Upcoming" ids, no game rules). boot() starts them together with the
// settings when the Dashboard is the first page; renderOverview then finds
// them in dashCached. Same requests and keys as before.
function dashFixedReads() {
  return {
    ...dashPublicReads(),
    skins: dashCached("skins", () => sb(`skins?user_id=eq.${USER_ID}&select=id,name,category,bonus_type,bonus_value,bonus_level1,bonus_type2,bonus_value2,bonus_level2,bonus_type3,bonus_value3,bonus_level3,bonus_type4,bonus_value4,bonus_level4,display_group,owned,current_level,max_level,count_in_max`)),
    player_heroes: dashCached("player_heroes", () => sb(`player_heroes?select=id,hero_id,current_level,current_stars&user_id=eq.${USER_ID}`)),
  };
}
// The ones that are the same for everyone (public reads): a first visit
// starts them while its guest sign-in is still on the way.
function dashPublicReads() {
  return {
    buff: dashCached("buff", async () => {
      if (!BUFF_TABLE_ID) {
        // One request: the buff table with its columns and rows (was the
        // table lookup, then columns + rows).
        // It also brings the columns in menu order ("cs"), which boot's
        // loadBuffCategories takes instead of reading them again.
        const [tb] = (await sb(`buff_tables?select=id,buff_columns(id,name,category),buff_rows(id,name,buff_cells(value,column_id)),cs:buff_columns(id,name,category)&cs.order=sort_order.asc&user_id=eq.${PROGRESSION_OWNER_ID}&name=neq.VIP%20Tier&order=created_at.asc&limit=1`)) || [];
        if (tb && !BUFF_TABLE_ID) BUFF_TABLE_ID = tb.id;
        if (tb) BUFF_SORTED_COLS = { id: tb.id, cols: tb.cs || [] };
        if (tb && tb.id === BUFF_TABLE_ID) return [tb.buff_columns || [], tb.buff_rows || []];
      }
      await ensureBuffTable();
      return Promise.all([
        sb(`buff_columns?table_id=eq.${BUFF_TABLE_ID}&select=id,name,category`),
        sb(`buff_rows?table_id=eq.${BUFF_TABLE_ID}&select=id,name,buff_cells(value,column_id)`),
      ]);
    }),
    heroes: ngHeroRows(),
    star_stats: dashCached("star_stats", () => sb(`hero_gen_star_stats?select=generation,step,atk_pct,def_pct,shards&order=generation,step`)),
    widget_stats: dashCached("widget_stats", () => sb(`hero_gen_widget_stats?select=generation,level,leth_pct,hp_pct&order=generation,level`)),
    vip: loadVipTable(),
  };
}
