    rows.forEach((r) => { if (r.stat_type !== stat) return; if (isUpcomingRow(table, r) && rel === Infinity) rel = opts.length; opts.push(Number(r.value_pct)); });
    return (rel === Infinity ? opts[opts.length - 1] : [0, ...opts][rel]) || 0;
