    if (e.target.closest("[data-mpnnext]")) { MP_NEW.step = Math.min(3, MP_NEW.step + 1); drawNew(); const f = host.querySelector("[data-mpnname]"); if (f && matchMedia("(min-width: 701px)").matches) f.focus(); return; }
