    const r = ng ? rows.find((x) => x.hero && String(x.hero.id) === ng[2]) : null;
    if (r && (ng[1] === "s" ? r.step >= 30 : !r.hasWidget || r.wLevel >= widgetMaxLevel())) return { until: minus1(packStartOfToday()), maxed: true };
