        const pool = ks.filter((k) => isNeeded(k));
        let best = (pool[0] || ks[0]) || null, bs = -1;
        (pool.length ? pool : ks).forEach((k) => { const sh = planTot[k] > 0 ? (r.gives[k] * (r.count || 1)) / planTot[k] : 0; if (sh > bs + 1e-9) { bs = sh; best = k; } });
        let keys = ks.slice(0, 6);
