          const k = Math.max(1, Math.min(tiers, p.choice ? parts.length : (Number(p.row) || 0) + 1));
          return { kind: "opt", steps, k, pick: steps.map((st, i) => (i < parts.length ? tagIdx(parts[i]) : 0)) };
