      const line = nf ? t(nf === 1 ? "pkb_ev_swap1" : "pkb_ev_swap").replace("{n}", nf).replace("{pack}", tb.title || "") : other ? t("pkb_ev_follows").replace("{pack}", other.title || "") : pkbResetText(xl.reset) || "";
