  if (extra.length) {
    let g = groups.find((x) => x.title === "Hero Shards");
    if (!g) { g = { title: "Hero Shards", items: [] }; groups.push(g); }
    extra.forEach((n) => g.items.push({ name: n, icon: BP_EXTRA_ICONS[n] }));
  }
  const isl = BP_ISLAND_ITEMS.filter((n) => !all.has(n));
