    if (!g) { g = { title: "Islands", items: [] }; const sp = groups.findIndex((x) => /Speedups$/.test(x.title)); groups.splice(sp < 0 ? groups.length : sp, 0, g); }
    isl.forEach((n) => g.items.push({ name: n, icon: BP_EXTRA_ICONS[n] }));
