const BP_ISLAND_ITEMS = ["Life Essence", "Mythic Island Shards", "Mark of Revival", "Glorious Tome", "Lucky Glorious Tome Chest"];
const BP_EXTRA_ICONS = { "Life Essence": "icons/life-essence.png", "Mythic Island Shards": "icons/island-shard.png", "Mark of Revival": "icons/mark-of-revival.png", "Glorious Tome": "icons/glorious-tome.png", "Lucky Glorious Tome Chest": "icons/lucky-glorious-tome-chest.png", "Marks of Valor": "icons/hall-marks.png", "Mystery Points": "icons/mystery-pts.png", "Widget Chest": "icons/hero-widgets.png", "Mythic General Hero Lucky Box": "icons/mythic-hero-lucky-box.png" };
function bpIcon(item) {
  if (item.icon) return item.icon;
  const name = item.name;
  if (itemRegIcon(name)) return itemRegIcon(name);
  const hm = /^(.+) (Shards|Widgets)$/.exec(String(name));
  if (hm && HERO_IMG_BY_NAME[hm[1]]) return hm[2] === "Widgets" ? HERO_ITEM_ICON.widget : HERO_ITEM_ICON.shard(HERO_RARITY_BY_NAME[hm[1]]);
  if (EXPERT_INVENTORY_ICONS[name]) return EXPERT_INVENTORY_ICONS[name];
  if (BP_CHEST_ICONS[name]) return BP_CHEST_ICONS[name];
  if (BP_SHARD_ICONS[name]) return BP_SHARD_ICONS[name];
  if (BP_EXTRA_ICONS[name]) return BP_EXTRA_ICONS[name];
  if (/^XP 10/.test(name)) return "icons/XP-Component.png";
  if (/speedup/i.test(name)) {
    const type = (name.match(/^(Construction|Troop|Research|Expert) Speedup/) || [])[1];
    return "icons/speedup-" + (type ? type.toLowerCase() : "general") + ".png";
  }
  const custom = packCustomResource(name);
  if (custom && custom.icon) return custom.icon;
  const lower = name.toLowerCase();
  const k = Object.keys(MATERIAL_ICONS).find((x) => lower.includes(x));
  return k ? MATERIAL_ICONS[k] : "";
}
