// Builds a human-readable label for a progression row, e.g.
// "Legendary T5 \u26053.2" or "Lv.42" (drops a lone ".0" stage suffix).
const CHIEF_GEAR_TIER_SHORT = {
  Common: "Green",
  Rare: "Blue",
  Epic: "Purple",
  "Epic T1": "Purple T1",
  Mythic: "Gold",
  "Mythic T1": "Gold T1",
  "Mythic T2": "Gold T2",
  Legendary: "Red",
  "Legendary T1": "Red T1",
  "Legendary T2": "Red T2",
  "Legendary T3": "Red T3",
  "Legendary T4": "Red T4",
  "Legendary T5": "Red T5",
  "Legendary T6": "Red T6",
};
function rowLabel(r) {
  if (r.display_label) return r.display_label;
  if (r.tier) return `${r.tier}${r.stars != null ? " \u2605" + r.stars : ""}${r.stage != null && r.stage !== "0" ? "." + r.stage : ""}`;
  return `Lv.${r.level}${r.stage && r.stage !== "0" ? "." + r.stage : ""}`;
}
function chiefGearRowLabel(r) {
  if (r.display_label) return r.display_label;
  if (r.tier) return `${CHIEF_GEAR_TIER_SHORT[r.tier] || r.tier}${r.stars != null ? " \u2605" + r.stars : ""}${r.stage != null && r.stage !== "0" ? "." + r.stage : ""}`;
  return rowLabel(r);
}
// Extracts the numeric percentage from a stat string like "+9.35%".
function parseStatPct(stat) {
  if (!stat) return null;
  const m = String(stat).match(/-?\d+(\.\d+)?/);
  return m ? Number(m[0]) : null;
}

// ============================================================
// CHIEF CHARMS CALCULATOR
// 18 charms total (6 gear pieces x 3 charm slots each), levels
// 1-18 with sub-levels from level 4 onward (75 steps total).
// Each charm boosts both Lethality and Health for its troop type.
// Cost table and per-level stat curve sourced from the community
// wiki (wostools.net); CHARM_LEVELS defines the exact step order.
// ============================================================
// Charm level data (levels, per-step material costs, cumulative Lethality/
// Health %) now lives in the `charm_levels` table (Admin-editable), not
// hardcoded. Loaded once via ensureCharmLevelsData().
let CHARM_LEVELS = [];
let CHARM_LEVEL_ROWS = []; // the rows (with ids) for the "Upcoming" ticks
let CHARM_STEP_COST = {};
let CHARM_CUMULATIVE = {};
let CHARM_CUMULATIVE_STAT = {};
let CHARM_LEVELS_LOADED = false;
let CHARM_LEVELS_PROMISE = null;
async function ensureCharmLevelsData() {
  // Callers running at the same time share one in-flight download.
  if (CHARM_LEVELS_LOADED) return CHARM_LEVELS_PROMISE;
  CHARM_LEVELS_LOADED = true;
  CHARM_LEVELS_PROMISE = (async () => {
  const rows = await sb(`charm_levels?select=${upId("charm_levels")}level_label,sort_order,guides_cost,designs_cost,secrets_cost,cumulative_pct&order=sort_order.asc`);
  CHARM_LEVELS = rows.map((r) => r.level_label);
  CHARM_LEVEL_ROWS = rows;
  CHARM_STEP_COST = {};
  CHARM_CUMULATIVE = {};
  CHARM_CUMULATIVE_STAT = {};
  let g = 0, d = 0, s = 0;
  rows.forEach((r) => {
    if (r.level_label !== "0") {
      CHARM_STEP_COST[r.level_label] = [Number(r.guides_cost), Number(r.designs_cost), Number(r.secrets_cost)];
      g += Number(r.guides_cost); d += Number(r.designs_cost); s += Number(r.secrets_cost);
    }
    CHARM_CUMULATIVE[r.level_label] = [g, d, s];
    CHARM_CUMULATIVE_STAT[r.level_label] = Number(r.cumulative_pct);
  });
  })().catch((e) => { CHARM_LEVELS_LOADED = false; throw e; });
  return CHARM_LEVELS_PROMISE;
}
// The 6 gear pieces, grouped by which troop type they buff.
const CHARM_PIECES = [
  { key: "helmet", name: "Helmet", troop: "Lancer" },
  { key: "watch", name: "Watch", troop: "Lancer" },
  { key: "jacket", name: "Jacket", troop: "Infantry" },
  { key: "pants", name: "Pants", troop: "Infantry" },
  { key: "ring", name: "Ring", troop: "Marksman" },
  { key: "cane", name: "Cane", troop: "Marksman" },
];
const CHARM_CALC_STATE = {};
CHARM_PIECES.forEach((p) => (CHARM_CALC_STATE[p.key] = [0, 1, 2].map(() => ({ current: "0", target: "18" }))));

// Builds <option> tags for a charm/gear level <select> (up to the user's cap).
function levelOptions(selected) {
  const cap = charmCapIdx();
  return CHARM_LEVELS.map((l, i) => `<option value="${l}" ${l === selected ? "selected" : ""}${i > cap ? ' class="opt-up"' : ""}>${l === "0" ? "0" + t("none_suffix") : l}${esc(upcomingTag(i > cap))}</option>`).join("");
}
// Last charm level that's out in the game.
function charmReleasedIdx() { return releasedLastIdx("charm_levels", CHARM_LEVEL_ROWS.length === CHARM_LEVELS.length ? CHARM_LEVEL_ROWS : CHARM_LEVELS.map(() => ({}))); }
// ---- What is open in the person's state (Chief Charm / Chief Gear / Hero Gear) ----
// "My max" was removed (the old calc_state "gear_caps" is
// ignored, not deleted). The cap is what is open: released levels, the
// state-age locks and level unlocks, skipped when a piece is already past.
// No state age = everything open. Higher levels stay pickable as targets
// ("· Upcoming"); "Max", "Max everything", the Troops Stats max and the
// Dashboard max stop at the cap.
function charmCapIdx() {
  // Not past a level that isn't open yet in the person's state
  // (12 – 16 come with Gen 7, 17 – 18 with Gen 8).
  const lk = charmLockCapIdx();
  return lk != null ? Math.min(lk, charmReleasedIdx()) : charmReleasedIdx();
}
// Charm levels by state age: [timeline key, last open level before it].
// A lock is skipped once a charm is already past it.
const CHARM_STATE_LOCKS = [["charm 11.1 16", "11"], ["charm 16.1 18", "16"]];
function charmLockCapIdx() {
  for (const [key, lv] of CHARM_STATE_LOCKS) {
    const at = CHARM_LEVELS.indexOf(lv);
    if (at < 0 || !stateNotYet("gear", key)) continue;
    if (CHARM_PIECES.some((p) => (CHARM_CALC_STATE[p.key] || []).some((slot) => CHARM_LEVELS.indexOf(String(slot.current)) > at))) continue;
    return at;
  }
  return null;
}
function charmCapLabel() { return CHARM_LEVELS[charmCapIdx()] ?? "0"; }
function chiefGearReleasedIdx() { return Math.max(0, releasedLastIdx("progression_rows", CHIEF_GEAR_ROWS || [])); }
function chiefGearLastIdx() { return Math.max(0, (CHIEF_GEAR_ROWS || []).length - 1); }
function chiefGearCapIdx() {
  // Not past T4 before Gen 4 heroes are out in the person's state (T5 – T6
  // come with Gen 4), nor into Legendary before it opens (day 180).
  const cap = Math.min(chiefGearReleasedIdx(), chiefGearT5Locked() ? chiefGearLastBeforeIdx(/legendary t[56]/i) : chiefGearLastIdx());
  return chiefLegendaryOn() ? cap : Math.min(cap, chiefGearLastEpicIdx());
}
// T5 – T6 wait for Gen 4 in the person's state, unless a piece is already there.
function chiefGearT5Locked() {
  if (!stateNotYet("gear", "chief gear t5 t6")) return false;
  const lastT4 = chiefGearLastBeforeIdx(/legendary t[56]/i);
  return !CHIEF_GEAR_PIECES.some((p) => ((CHIEF_GEAR_STATE[p.key] || {}).from ?? -1) > lastT4);
}
// Last row before the first row whose tier matches re (or the last row).
function chiefGearLastBeforeIdx(re) {
  const rows = CHIEF_GEAR_ROWS || [];
  const i = rows.findIndex((r) => re.test(String(r.tier || "")));
  return i > 0 ? i - 1 : Math.max(0, rows.length - 1);
}
// Last row before the Legendary tiers.
function chiefGearLastEpicIdx() {
  const rows = CHIEF_GEAR_ROWS || [];
  const i = rows.findIndex((r) => /^legendary/i.test(String(r.tier || "")));
  return i > 0 ? i - 1 : Math.max(0, rows.length - 1);
}
// Legendary Chief Gear is open unless the state age says it isn't yet
// (day 180). A piece already at Legendary keeps it open.
function chiefLegendaryOn() {
  if (!stateNotYet("gear", "legendary chief gear")) return true;
  const lastEpic = chiefGearLastEpicIdx();
  return CHIEF_GEAR_PIECES.some((p) => (CHIEF_GEAR_STATE[p.key] || {}).from > lastEpic);
}
// Enhance Combined rows 0..100 are Enhance, 101..200 Empower (Mithril).
// Every level can be picked; ones not open yet are marked in the lists.
function heroTrackPickIdx(track) {
  const rows = (HERO_GEAR_TABLES_CACHE && HERO_GEAR_TABLES_CACHE[track]) || [];
  return Math.max(0, rows.length - 1);
}
// "Max": the last level that's out and open in the person's state.
function heroTrackReleasedIdx(track) { return Math.max(0, releasedLastIdx("progression_rows", (HERO_GEAR_TABLES_CACHE && HERO_GEAR_TABLES_CACHE[track]) || [])); }
function heroTrackCapIdx(track) { return Math.min(heroTrackPickIdx(track), heroTrackReleasedIdx(track)); }
// Page name from the menu, in the chosen language.
function navLabel(tab) {
  const e = NAV_PAGE_LABELS[tab] || {};
  return e[LANG] || e.en || tab;
}
// The level cap as a line in the Settings card (new planner layout).
// "Set all" (Chief Gear, Charms, Heroes Gears): a small "⇅ Set all ▾" button
// next to the troop name opens the Now → Target dropdowns. Open / closed is kept per page for the visit.
const SETALL_OPEN = {};
function setAllWrapHtml(key, headHtml, rowsHtml) {
  const open = !!SETALL_OPEN[key];
  return `<div class="sa-wrap${open ? " open" : ""}" data-sakey="${esc(key)}">
    <div class="sa-head">${headHtml}<button type="button" class="sa-btn" data-satoggle aria-expanded="${open}">&#8645; ${esc(t("set_all_short"))} <span class="sa-car">${open ? "&#9652;" : "&#9662;"}</span></button></div>
    <div class="sa-box">${rowsHtml}</div></div>`;
}
document.addEventListener("click", (ev) => {
  const b = ev.target.closest && ev.target.closest("[data-satoggle]");
  if (!b) return;
  const w = b.closest(".sa-wrap"); if (!w) return;
  const open = !w.classList.contains("open");
  w.classList.toggle("open", open); SETALL_OPEN[w.dataset.sakey] = open;
  b.setAttribute("aria-expanded", String(open));
  const car = b.querySelector(".sa-car"); if (car) car.innerHTML = open ? "&#9652;" : "&#9662;";
});

// Renders the 3-troop-type x 2-piece x 3-charm-slot calculator,
// each slot with its own current\u2192target level pair.
let CHARM_STATE_LOADED = false;
let CHARM_STATE_PROMISE = null;
// Loads any saved Charm selections into CHARM_CALC_STATE. Safe to call
// from anywhere; only fetches once per session. Callers running at the
// same time share one load (so nobody sees the state before the saved
// selections are applied), and a failed load is retried on the next call.
async function ensureCharmData() {
  if (CHARM_STATE_LOADED) return CHARM_STATE_PROMISE;
  CHARM_STATE_LOADED = true;
  CHARM_STATE_PROMISE = loadCharmData().catch((e) => { CHARM_STATE_LOADED = false; throw e; });
  return CHARM_STATE_PROMISE;
}
async function loadCharmData() {
  await ensureCharmLevelsData();
  const saved = await loadCalcState("charm");
  if (!saved && !IS_OWNER) CHARM_PIECES.forEach((p) => CHARM_CALC_STATE[p.key].forEach((slot) => { slot.target = slot.current; }));
  if (saved) {
    CHARM_PIECES.forEach((p) => {
      if (Array.isArray(saved[p.key])) {
        saved[p.key].forEach((slot, i) => {
          if (CHARM_CALC_STATE[p.key][i] && slot) {
            if (slot.current) CHARM_CALC_STATE[p.key][i].current = slot.current;
            if (slot.target) CHARM_CALC_STATE[p.key][i].target = slot.target;
          }
        });
      }
    });
  }
}


// ============================================================
// PACKS -> CALCULATOR PAGES
// A pack table can be pointed at one or more calculator pages, and each of
// its columns labelled with the resource it grants (plus which column holds
// the price). Those pages then show what the packs would cost to cover what
// they still need. The links live in calc_state, so no database change is
// needed and they follow the user across devices.
