  "random chief gear chest": "Random Chief Gear Chest", "chief gear random chest": "Random Chief Gear Chest", "random chest chief gear": "Random Chief Gear Chest", "random chief gear material chest": "Random Chief Gear Chest",
  "random chief charm chest": "Random Charm Chest", "chief charm random chest": "Random Charm Chest", "random chest chief charm": "Random Charm Chest", "random charm material chest": "Random Charm Chest", "custom pet chest": "Pet Chest",
  "1hr research speeds": "Research Speedup 1h", "1hr troops speeds": "Troop Speedup 1h", "1hr troop speeds": "Troop Speedup 1h", "1hr construction speeds": "Construction Speedup 1h", "1hr constructions speeds": "Construction Speedup 1h",
  "1hr": "Speedup 1h", "5min": "Speedup 5m", "1min": "Speedup 1m", "3hr": "Speedup 3h", "8hr": "Speedup 8h", "3min": "Speedup 3m",
  "fc crate": "FC Crate", "fire crystal crate": "FC Crate", "fire crystal weekly card crate": "FC Crate",
  "fire crystal chest": "FC Chest", "fc chest": "FC Chest",
  "fc": "Fire Crystal", "fire crystals": "Fire Crystal", "fcs": "FC Shard", "fc shards": "FC Shard", "fire crystal shard": "FC Shard", "fire crystal shards": "FC Shard",
  "rfc": "Refined FC", "refined fire crystal": "Refined FC", "sigil": "General Sigils", "sigils": "General Sigils", "general sigil": "General Sigils",
  "book": "Books of Knowledge", "books": "Books of Knowledge", "essence stone": "Essence Stones", "design plans": "Design Plan", "charm guide": "Charm Guides", "charm design": "Charm Designs",
