  const budDay = BUDGET_TARGET ? packParseDay(BUDGET_TARGET) : null;
  const autoBy = budDay && budDay >= today ? budDay : new Date(today.getTime() + 56 * DAY);
  const autoByFromBudgets = !!(budDay && budDay >= today);
  const byDay = st.myBy ? packParseDay(st.myBy) : autoBy;
  // Done day of a plan: day by day from this week's Monday (the plan's
