  const wksTxt = (d) => { if (!d) return "—"; const w = Math.ceil((d - today) / DAY / 7); return w <= 0 ? t("rl_now") : `${fmt(w)} ${t("rl_wks")}`; };
  const speeds = rfcSpeeds();
  const cheapest = speeds[0], fastest = speeds[speeds.length - 1];
  // Nothing needed: keep the plan as it is (no reason to move T12 / Budgets).
