    const prev = snap[calcKey];
    // The saved copy comes back from the database with its item names in a
    // different order, so compare by name (not by text) - otherwise every
    // page's first visit looked like a change and threw away Budgets and the
    // My Purchases suggestions for nothing.
    const sig = (gs) => JSON.stringify((gs || []).map((g) => [g.label || null, Object.keys(g.totals || {}).filter((k) => Number(g.totals[k])).sort().map((k) => [k, Math.round(Number(g.totals[k]) * 1000) / 1000])]));
