        const st = s && typeof s === "object" ? s : { from: -1, to: IS_OWNER ? petMaxIdx(pet) : -1 };
        const pct = (i) => { for (let k = Math.min(i, levels.length - 1); k >= 0; k--) if (levels[k].atk_def_pct != null) return Number(levels[k].atk_def_pct) * 100; return 0; };
        if (st.to > st.from) gain += Math.max(0, pct(st.to) - (st.from >= 0 ? pct(st.from) : 0));
