    const stageDay = (g, i) => (due[i] != null ? due[i] : g.page && lateKeys.includes(g.page) ? null : mainDay);
    const partOf = (g, i) => { const sd = stageDay(g, i); return dlPlan && sd != null ? dl.parts.find((x) => !x.late && x.day === sd) : null; };
