// Skills renamed in the data:
// saved levels move to the new name, so nobody loses them.
const EXPERT_SKILL_RENAMES = { Fabian: { "Dawn Hymn": "Battle Bulwark" }, Justus: { "Tresure Seeker": "Treasure Seeker" } };
// Renames made in Admin → Experts → Roster are added in site_config
