  const extra = typeof siteConfig === "function" ? siteConfig("expert_skill_renames", null) : null;
  if (Array.isArray(extra)) extra.forEach((x) => { if (x && x.hero && x.from && x.to) out.push({ hero: String(x.hero), from: String(x.from), to: String(x.to) }); });
