// Same logic as the Experts page's computeBaseTroopStats(): all 10 experts'
// level-based base stats, plus Romulus's Last Line & Spirit of Aeetis and
// Gareth's Porcupine & Undefeated Will skills. Troop-agnostic (same bonus
// applies to all troop types).
function computeExpertsTroopStatsGlobal(useMax) {
  const totals = { Attack: 0, Defense: 0, Lethality: 0, Health: 0 };
  const ALL_EXPERTS = EXPERTS_LIST.map((e) => e.key);
  ALL_EXPERTS.forEach((hero) => {
    if (!unlockedFor("experts", hero, EXPERTS_UNLOCKED_GLOBAL && EXPERTS_UNLOCKED_GLOBAL[hero])) return;
    const rows = (EXPERT_AFFINITY_CACHE_GLOBAL && EXPERT_AFFINITY_CACHE_GLOBAL[hero]) || [];
    if (!rows.length) return;
    if (useMax) {
      const row = rows[Math.max(0, releasedLastIdx("expert_affinity_nodes", rows))];
      if (row && row.stat_type) row.stat_type.split(",").forEach((statName) => { if (totals[statName] != null) totals[statName] += Number(row.stat_value) || 0; });
    } else {
      expertAddLevel(totals, rows, expertSavedLevel(EXPERTS_STATE_GLOBAL, hero, "current"));
    }
  });
  [
    ["Romulus", "Last Line"],
    ["Romulus", "Spirit of Aeetis"],
    ["Gareth", "Porcupine"],
    ["Gareth", "Undefeated Will"],
  ].forEach(([hero, skill]) => {
    if (!unlockedFor("experts", hero, EXPERTS_UNLOCKED_GLOBAL && EXPERTS_UNLOCKED_GLOBAL[hero])) return;
    const rows = (EXPERT_TROOP_SKILL_CACHE_GLOBAL && EXPERT_TROOP_SKILL_CACHE_GLOBAL[`${hero}|${skill}`]) || [];
    if (!rows.length) return;
    let row;
    if (useMax) {
      row = rows[Math.max(0, releasedLastIdx("expert_skill_nodes", rows))];
    } else {
      const st = EXPERTS_STATE_GLOBAL[hero] && EXPERTS_STATE_GLOBAL[hero].skills && EXPERTS_STATE_GLOBAL[hero].skills[skill];
      const cur = st ? st.current : 0;
      let match = null;
      rows.forEach((r) => {
        if (r.level <= cur) match = r;
      });
      row = match;
    }
    if (row && row.stat_type) {
      row.stat_type.split(",").forEach((statName) => {
        if (totals[statName] != null) totals[statName] += Number(row.stat_value) || 0;
      });
    }
  });
  return totals;
}

// ---- Experts Research (Dashboard wiring) ----
// Mirrors the logic in renderExpertsResearchPage(): general experts'
// rotation+main stat apply to all 3 troop types; Gareth's main stat is
// Lancers-only, Justus's is Infantry-only. Marksman gets general only.
let EXPERTS_RESEARCH_NODES_GLOBAL = null; // { expert: { pathNum: [rows] } }
let EXPERTS_RESEARCH_STATE_GLOBAL = null; // saved current/desired per expert/path
let EXPERTS_RESEARCH_UNLOCKED_GLOBAL = null;
async function ensureExpertsResearchDataGlobal() {
  if (EXPERTS_RESEARCH_NODES_GLOBAL) return;
  const [, rows, savedResearch, savedResearchUnlocked] = await Promise.all([
    ensureExpertsRosterGlobal(),
    loadExpertNodes("research"),
    loadCalcState("experts_research"),
    loadCalcState("experts_research_unlocked"),
  ]);
  EXPERTS_RESEARCH_NODES_GLOBAL = {};
  rows.forEach((r) => {
    if (!EXPERTS_RESEARCH_NODES_GLOBAL[r.expert]) EXPERTS_RESEARCH_NODES_GLOBAL[r.expert] = {};
    if (!EXPERTS_RESEARCH_NODES_GLOBAL[r.expert][r.path_number]) EXPERTS_RESEARCH_NODES_GLOBAL[r.expert][r.path_number] = [];
    EXPERTS_RESEARCH_NODES_GLOBAL[r.expert][r.path_number].push(r);
  });
  EXPERTS_RESEARCH_STATE_GLOBAL = savedResearch || {};
  EXPERTS_RESEARCH_UNLOCKED_GLOBAL = savedResearchUnlocked || {};
}
function expertsResearchPathNumbersGlobal(expert) {
  return Object.keys((EXPERTS_RESEARCH_NODES_GLOBAL && EXPERTS_RESEARCH_NODES_GLOBAL[expert]) || {})
    .map(Number)
    .sort((a, b) => a - b);
}
function expertsResearchPathCostGlobal(expert, pathNum, fromLevel, toLevel) {
  const pathRows = ((EXPERTS_RESEARCH_NODES_GLOBAL && EXPERTS_RESEARCH_NODES_GLOBAL[expert]) || {})[pathNum] || [];
  const stats = { ATK: 0, DEF: 0, DMG: 0, HP: 0 };
  pathRows.forEach((r) => {
    if (r.level > fromLevel && r.level <= toLevel) {
      if (stats[r.stat_type] != null) stats[r.stat_type] += Number(r.stat_value) || 0;
    }
  });
  const mainStat = EXPERT_MAIN_STAT_GLOBAL_MAP[expert];
  if (mainStat && stats[mainStat] != null) {
    const clampedFrom = Math.max(0, Math.min(200, fromLevel));
    const clampedTo = Math.max(0, Math.min(200, toLevel));
    const levelsCrossed = Math.max(0, clampedTo - clampedFrom);
    let rate = 0.01;
    // Troop-specific experts use the split path rate
    if (expertTroopKey(expert)) {
      rate = pathNum <= 3 ? 0.03 : 0.05;
    }
    stats[mainStat] += levelsCrossed * rate;
  }
  return stats;
}
function expertsResearchIsUnlockedGlobal(expert) {
  return unlockedFor("experts", expert, EXPERTS_RESEARCH_UNLOCKED_GLOBAL && EXPERTS_RESEARCH_UNLOCKED_GLOBAL[expert]);
}
// calcTroop: "Infantry" | "Lancer" | "Marksman". Returns {ATK,DEF,DMG,HP}.
function computeExpertsResearchTroopStatsGlobal(calcTroop, useMax) {
  const totals = { ATK: 0, DEF: 0, DMG: 0, HP: 0 };
  if (!EXPERTS_RESEARCH_NODES_GLOBAL) return totals;
  // Experts with no troop set on the roster count for every troop; the rest
  // only count for the troop they're set to.
  const includeExperts = new Set(EXPERTS_IN_ORDER_GLOBAL.filter((e) => !expertTroopKey(e)));
  expertsForTroop(calcTroop, EXPERTS_IN_ORDER_GLOBAL).forEach((e) => includeExperts.add(e));
  includeExperts.forEach((expert) => {
    if (!expertsResearchIsUnlockedGlobal(expert)) return;
    expertsResearchPathNumbersGlobal(expert).forEach((p) => {
      if (useMax) {
        const rows = (EXPERTS_RESEARCH_NODES_GLOBAL[expert][p] || []).slice().sort((a, b) => Number(a.level) - Number(b.level));
        const ri = releasedLastIdx("expert_research_nodes", rows);
        const stats = expertsResearchPathCostGlobal(expert, p, 0, ri >= rows.length - 1 ? 200 : ri < 0 ? 0 : Number(rows[ri].level) || 0);
        Object.keys(stats).forEach((k) => (totals[k] += stats[k]));
      } else {
        const st = (EXPERTS_RESEARCH_STATE_GLOBAL[expert] || {})[p] || { current: 0 };
        const stats = expertsResearchPathCostGlobal(expert, p, 0, st.current);
        Object.keys(stats).forEach((k) => (totals[k] += stats[k]));
      }
    });
  });
  return totals;
}

// The VIP Tier table's columns and rows, loaded once and shared by the
// Dashboard (ensureVipData) and the VIP page; kept for the visit (dashCached).
function loadVipTable() {
  return dashCached("vip_table", async () => {
    // One request: the table with its columns and rows embedded, in the same
    // order (was the table lookup, then columns + rows).
    const [tb] = (await sb(`buff_tables?name=eq.VIP Tier&user_id=eq.${PROGRESSION_OWNER_ID}&select=id,buff_columns(id,name),buff_rows(id,name,sort_order,buff_cells(value,column_id))&buff_columns.order=sort_order.asc&buff_rows.order=sort_order.asc`)) || [];
    if (!tb) return null;
    return { table: { id: tb.id }, columns: tb.buff_columns || [], rows: tb.buff_rows || [] };
  });
}
async function ensureVipData() {
  if (!VIP_ROWS_CACHE) {
    const vip = await loadVipTable();
    if (!vip) {
      VIP_ROWS_CACHE = [];
    } else {
      const { columns, rows } = vip;
      const colNameById = Object.fromEntries(columns.map((c) => [c.id, c.name]));
      VIP_ROWS_CACHE = rows.map((r) => {
        const entry = { name: r.name, id: r.id };
        r.buff_cells.forEach((c) => {
          if (c.value == null) return;
          entry[colNameById[c.column_id]] = Number(c.value);
        });
        return entry;
      });
    }
  }
  // Always re-read the saved tier (not just once) so switching VIP tier on
  // its own page is reflected the next time the dashboard renders.
  if (VIP_ROWS_CACHE.length) {
    const saved = await loadCalcState("vip_tier");
    VIP_SELECTED_INDEX = 0; // nothing picked yet = lowest tier
    if (saved) {
      const byName = VIP_ROWS_CACHE.findIndex((r) => r.name === saved.name);
      if (byName !== -1) VIP_SELECTED_INDEX = byName;
      else if (typeof saved.index === "number" && saved.index >= 0 && saved.index < VIP_ROWS_CACHE.length) VIP_SELECTED_INDEX = saved.index;
    }
  }
}

// ---- Extra bonus pages = pattern C ----
// Title with (i) (and Max), an answer card first (2 x 2 stat boxes: now,
// / max, amber "+N left", bar), then simple rows. Used by VIP, Alliance Tech,
// Facility, Tundra Album, Collection Gallery and Heroes Special Skills.
const BN_ABBR = { Attack: "ATK", Defense: "DEF", Lethality: "LETH", Health: "HP" };
const BN_STAT_ORDER = ["Attack", "Defense", "Lethality", "Health"];
function bnAbbr(s) { return BN_ABBR[s] || tStatLabel(s || ""); }
