const LEVEL_LOCK_CHOICES = {};
async function loadLevelLockChoices() {
  await Promise.all(Object.entries(LEVEL_LOCK_TARGETS).map(async ([k, d]) => {
    try { await d.load(); const c = d.choices(); LEVEL_LOCK_CHOICES[k] = c && c.length ? c : null; } catch (e) { LEVEL_LOCK_CHOICES[k] = null; }
  }));
}
function gameRulesSaved() { const v = siteConfig("game_rules", null); return v && typeof v === "object" ? v : {}; }
// Puts the built-in values back, then the admin's saved ones on top.
function applyGameRules() {
  const saved = gameRulesSaved();
  gameRules().forEach((r) => {
    try { r.set(JSON.parse(JSON.stringify(saved[r.key] != null ? saved[r.key] : r.def))); }
    catch (e) { console.error("rule", r.key, e); try { r.set(JSON.parse(JSON.stringify(r.def))); } catch (e2) { /* keep */ } }
  });
}
// Every name in the game tables (heroes, pets, experts and their skills /
// talents, cosmetics and their categories, pack tables and pack items,
// Backpack items, bonus names), so a new name can be translated in Admin
// without code: listed as "data:<name>" next to the built-in ones and saved
// in the same site_config "lang_<code>" (injectLangPack applies them).
// Read once per Admin visit (cleared when Admin opens, dropKeptGameData).
let GAME_NAME_TEXTS = null;
// Hides visitor-hidden pages from the menus (owner always sees everything).
function applyPageVisibility() {
  document.querySelectorAll("#topnavGroups .topnav-group").forEach((g) => {
    let visible = 0;
    g.querySelectorAll("button[data-tab]").forEach((b) => {
      if (b.hasAttribute("data-ownertab")) { if (b.style.display !== "none") visible++; return; }
      const hide = !IS_OWNER && isHiddenFromVisitors("page", b.dataset.tab);
      b.style.display = hide ? "none" : "";
      if (!hide) visible++;
    });
    if (g.id !== "adminNavGroup") g.style.display = visible ? "" : "none";
  });
}

// ---- Admin level tables, design B ----
// Type straight into the table; changed boxes turn orange and one bar
// ("N changes not saved · Undo · Save") saves only the changed rows, one at
// a time. o: { rowAttr, table, fields = "[data-f]", saveRow(id) (instead of a
// plain PATCH of the changed fields), after(), hide: [selectors] }.
let ADM_EDIT_DIRTY = 0;
window.addEventListener("beforeunload", (e) => { if (TAB === "adminpage" && admUnsavedCount()) { e.preventDefault(); e.returnValue = ""; } });
// Unsaved edits still on screen (a Save bar showing): the count, else 0 (a
// table redrawn or left keeps no stale count).
function admUnsavedCount() {
  if (!ADM_EDIT_DIRTY) return 0;
  return TAB === "adminpage" && content.querySelector(".adm-ebar:not([hidden])") ? ADM_EDIT_DIRTY : 0;
}
// Before leaving a section / page / sub-tab: true = go on (edits dropped).
function admConfirmLeave() {
  const n = admUnsavedCount();
  if (n && !confirm(t("adm_unsaved_leave").replace("{n}", n))) return false;
  ADM_EDIT_DIRTY = 0;
  return true;
}
// Sub-tabs and pickers inside a section (chips) redraw it too: ask first.
document.addEventListener("click", (e) => {
  if (TAB !== "adminpage" || !ADM_EDIT_DIRTY) return;
  const chip = e.target.closest && e.target.closest("#adminBody .adm-chip:not(.on)");
  if (chip && !admConfirmLeave()) { e.preventDefault(); e.stopImmediatePropagation(); }
}, true);

// ---- Heroes Special Skills editor (Jero/Natalia star-level bonuses, shared buff matrix) ----
// Reserved system category names that must never appear as "hero" choices,
// even though they live in the same shared buff_columns table.
const ADMIN_RESERVED_BUFF_CATEGORIES = new Set([
  "Album Buff", "Alliance Buff", "Attack", "Charm", "Chief", "Chief Bonus",
  "Defense", "Exp. Research", "Expert", "Facility", "Gallery",
  "Health", "Hero Gears", "Islands", "Lethality", "Pets", "Research", "Skins",
  "T12", "War Acd.",
]);


// Clears any text/number input's value when it's focused while showing a
// bare zero (0, 0.00, etc) so the user can start typing immediately instead
// of having to manually delete the placeholder zero first. Applies to every
// input across the whole app via event delegation, so it works uniformly
// without needing to be wired into each individual field.
document.addEventListener(
  "focusin",
  (e) => {
    const el = e.target;
    if (!el || el.tagName !== "INPUT") return;
    const type = (el.type || "text").toLowerCase();
    if (type !== "text" && type !== "number") return;
    if (/^0(\.0+)?$/.test(el.value.trim())) {
      el.value = "";
    }
  },
  true
);

// ---- Image upload to Supabase Storage (skin-images bucket) ----
// Any admin image input can get a "⬆ Upload" button beside it (rendered by
// uploadBtnHtml). Clicking opens a file picker; the file is uploaded and the
// public URL is written into the adjacent input.
// Pictures are cropped to their main part before upload (empty see-through
// borders off, at least 99% of the picture kept) and made at most 384 px,
// so every card shows them at the same size. Anything that can't be read
// (or has no see-through border) is uploaded as it is.
async function cropUploadImage(file) {
  if (!/^image\/(png|webp)$/.test(file.type || "")) return file;
  try {
    const bmp = await createImageBitmap(file);
    const W = bmp.width, H = bmp.height;
    const cv = document.createElement("canvas"); cv.width = W; cv.height = H;
    const cx = cv.getContext("2d"); cx.drawImage(bmp, 0, 0);
    const px = cx.getImageData(0, 0, W, H).data;
    const rows = new Array(H).fill(0), cols = new Array(W).fill(0);
    let fx0 = W, fy0 = H, fx1 = -1, fy1 = -1, total = 0;
    for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
      const a = px[(y * W + x) * 4 + 3];
      if (a > 40) { rows[y]++; cols[x]++; }
      if (a > 12) { total += a; if (x < fx0) fx0 = x; if (x > fx1) fx1 = x; if (y < fy0) fy0 = y; if (y > fy1) fy1 = y; }
    }
    if (fx1 < 0) return file;
    // The main part: rows/columns at least half as full as the fullest one.
    const span = (arr) => { const max = Math.max(...arr); let a = 0, b = arr.length - 1; while (arr[a] < max / 2) a++; while (arr[b] < max / 2) b--; return [a, b + 1]; };
    const [x0, x1] = span(cols), [y0, y1] = span(rows);
    const kept = (b) => { let sum = 0; for (let y = b[1]; y < b[3]; y++) for (let x = b[0]; x < b[2]; x++) { const a = px[(y * W + x) * 4 + 3]; if (a > 12) sum += a; } return sum; };
    let box = [fx0, fy0, fx1 + 1, fy1 + 1];
    for (let k = 0; k < 40; k++) {
      const m = Math.round((0.04 + 0.02 * k) * Math.max(x1 - x0, y1 - y0));
      const b = [Math.max(fx0, x0 - m), Math.max(fy0, y0 - m), Math.min(fx1 + 1, x1 + m), Math.min(fy1 + 1, y1 + m)];
      if (kept(b) >= 0.99 * total) { box = b; break; }
    }
    const bw = box[2] - box[0], bh = box[3] - box[1];
    const scale = Math.min(1, 384 / Math.max(bw, bh));
    if (bw === W && bh === H && scale === 1) return file;
    const out = document.createElement("canvas");
    out.width = Math.max(1, Math.round(bw * scale)); out.height = Math.max(1, Math.round(bh * scale));
    const ox = out.getContext("2d"); ox.imageSmoothingQuality = "high";
    ox.drawImage(cv, box[0], box[1], bw, bh, 0, 0, out.width, out.height);
    const blob = await new Promise((res) => out.toBlob(res, "image/png"));
    return blob ? new File([blob], file.name.replace(/\.[^.]*$/, "") + ".png", { type: "image/png" }) : file;
  } catch (e) {
    return file;
  }
}
async function uploadImageToStorage(file) {
  file = await cropUploadImage(file);
  const ext = (file.name.split(".").pop() || "png").toLowerCase().replace(/[^a-z0-9]/g, "") || "png";
  const path = `${crypto.randomUUID()}.${ext}`;
  const res = await fetch(`${SUPABASE_URL}/storage/v1/object/skin-images/${path}`, {
    method: "POST",
    // The bucket only lets the owner write, so this must carry the owner's
    // session token (the bare anon key is rejected with 403).
    headers: { apikey: SUPABASE_KEY, Authorization: `Bearer ${(CURRENT_SESSION && CURRENT_SESSION.access_token) || SUPABASE_KEY}`, "Content-Type": file.type || "application/octet-stream", "x-upsert": "true" },
    body: file,
  });
  if (!res.ok) {
    let detail = "";
    try { detail = (await res.json()).message || ""; } catch (_) {}
    throw new Error(`Upload failed (${res.status}${detail ? ": " + detail : ""})`);
  }
  return `${SUPABASE_URL}/storage/v1/object/public/skin-images/${path}`;
}
function uploadBtnHtml() {
  return `<button type="button" class="btn ghost small" data-imgupload title="Upload image" style="padding:4px 8px; white-space:nowrap;">&#8679; Upload</button>`;
}
let IMG_UPLOAD_PICKER = null;
document.addEventListener("click", (e) => {
  const btn = e.target.closest("[data-imgupload]");
  if (!btn) return;
  e.preventDefault();
  const input = btn.previousElementSibling && btn.previousElementSibling.tagName === "INPUT" ? btn.previousElementSibling : null;
  if (!input) return;
  if (!IMG_UPLOAD_PICKER) {
    IMG_UPLOAD_PICKER = document.createElement("input");
    IMG_UPLOAD_PICKER.type = "file";
    IMG_UPLOAD_PICKER.accept = "image/*";
    IMG_UPLOAD_PICKER.style.display = "none";
    document.body.appendChild(IMG_UPLOAD_PICKER);
  }
  IMG_UPLOAD_PICKER.onchange = async () => {
    const file = IMG_UPLOAD_PICKER.files && IMG_UPLOAD_PICKER.files[0];
    IMG_UPLOAD_PICKER.value = "";
    if (!file) return;
    const orig = btn.innerHTML;
    btn.innerHTML = "Uploading\u2026";
    btn.disabled = true;
    try {
      const url = await uploadImageToStorage(file);
      input.value = url;
      input.dispatchEvent(new Event("input", { bubbles: true }));
      input.dispatchEvent(new Event("change", { bubbles: true }));
      toast("Image uploaded \u2014 remember to Save");
    } catch (err) {
      toast(err && err.message ? err.message : "Upload failed", true);
    } finally {
      btn.innerHTML = orig;
      btn.disabled = false;
    }
  };
  IMG_UPLOAD_PICKER.click();
});

// Small login control in the sidebar: lets the owner log in with a real
// email/password to unlock Admin. Everyone else stays on their automatic
// anonymous session and never sees anything beyond a "Owner login" link.
function renderOwnerLoginUI() {
  const el = document.getElementById("ownerLoginArea");
  document.getElementById("adminNavGroup").style.display = IS_OWNER ? "block" : "none";
  // Backpack and Budgets are owner-only pages.
  document.querySelectorAll("[data-ownertab]").forEach((b) => { b.style.display = visitorCan(b.dataset.access || b.dataset.tab) ? "" : "none"; });
  applyPageVisibility();

  const user = CURRENT_SESSION && CURRENT_SESSION.user;
  const signedIn = !!(user && user.email && !user.is_anonymous);
  renderAccountButton();
  const outEl = document.getElementById("ownerLogoutArea");
  if (outEl) outEl.innerHTML = "";
  if (signedIn) {
    el.innerHTML = `
      ${user.email_confirmed_at || user.confirmed_at ? "" : `<div class="meta" style="font-size:10.5px; color:var(--amber); margin-bottom:10px;">${esc(t("confirm_email_hint"))}</div>`}
    `;
    if (outEl) outEl.innerHTML = `<button class="btn ghost small" id="ownerLogoutBtn" style="width:100%;">${esc(t("log_out"))}</button>`;
    document.getElementById("ownerLogoutBtn").addEventListener("click", async () => {
      await supabaseClient.auth.signOut();
      // Every cached calculator state belongs to the account that just left:
      // reload so the fresh (anonymous) session starts clean.
      // (Admin is for the owner only: don't reopen it for the visitor.)
      try { if (localStorage.getItem("last_tab") === "adminpage") localStorage.setItem("last_tab", "overview"); } catch (e) { /* storage blocked */ }
      location.hash = "";
      location.reload();
    });
    return;
  }

  el.innerHTML = `
    <div class="meta" style="font-size:12px; margin-bottom:10px;">${esc(t("account_pitch"))}</div>
    <button class="btn" id="ownerLoginOpenBtn" style="width:100%; margin-bottom:8px;">${esc(t("sign_in_or_create"))}</button>
    <div style="border-top:1px solid var(--line); margin:12px 0 10px;"></div>`;
  document.getElementById("ownerLoginOpenBtn").addEventListener("click", () => { closeAllTopnavDropdowns(); openAccountModal("signin"); });
}
// The account button: "Sign in" for guests, the person's initial with a green
// dot when signed in; its panel starts with their name / email.
function renderAccountButton() {
  const btn = document.getElementById("topnavSettingsBtn"), head = document.getElementById("accHead");
  if (!btn) return;
  const user = CURRENT_SESSION && CURRENT_SESSION.user;
  const signedIn = !!(user && user.email && !user.is_anonymous);
  const nameEl = document.getElementById("commanderName");
  const name = (nameEl && nameEl.value.trim()) || (signedIn ? user.email.split("@")[0] : "");
  if (signedIn) {
    btn.className = "tn-acc in";
    btn.textContent = (name.charAt(0) || "?").toUpperCase();
    btn.title = user.email;
    if (head) head.innerHTML = `<div class="acc-head"><span class="acc-av">${esc((name.charAt(0) || "?").toUpperCase())}</span><span style="min-width:0;"><b>${esc(name)}</b><span class="meta">${esc(user.email)}</span><span class="meta" style="display:block; color:var(--good);">&#10003; ${IS_OWNER ? esc(t("logged_in_owner")) : esc(t("acc_signed_in"))}</span></span></div>`;
  } else {
    btn.className = "tn-acc";
    btn.textContent = t("acc_sign_in");
    btn.title = t("sign_in_or_create");
    if (head) head.innerHTML = "";
  }
  fillMenuStyleRow();
}

// Sign in / create account for everyone. Creating an account upgrades the
// visitor's anonymous session in place (same user id), so everything they
// saved in this browser carries over. The owner email unlocks Admin.
function openAccountModal(mode) {
  let modal = document.getElementById("ownerLoginModal");
  if (!modal) {
    modal = document.createElement("div");
    modal.id = "ownerLoginModal";
    modal.className = "modal-overlay";
    document.body.appendChild(modal);
    modal.addEventListener("click", (e) => { if (e.target === modal) modal.style.display = "none"; });
  }
  const isCreate = mode === "create";
  const tabBtn = (m, label) => `<button type="button" class="btn small ${m === mode ? "" : "ghost"}" data-accmode="${m}" style="flex:1;">${esc(label)}</button>`;
  modal.innerHTML = `
    <div class="modal-box" style="max-width:360px;">
      <div style="display:flex; gap:6px; margin-bottom:10px;">${tabBtn("signin", t("log_in"))}${tabBtn("create", t("create_account"))}</div>
      <p class="desc" style="margin:0 0 10px;">${esc(t(isCreate ? "create_account_desc" : "sign_in_desc"))}</p>
      <div id="accGoogle"></div>
      <div style="display:flex; flex-direction:column; gap:8px;">
        <input type="email" id="ownerLoginEmail" placeholder="${esc(t("email_placeholder"))}" autocomplete="email" style="width:100%;" />
        <input type="password" id="ownerLoginPassword" placeholder="${esc(t("password_placeholder"))}" autocomplete="${isCreate ? "new-password" : "current-password"}" style="width:100%;" />
        <div class="err" id="ownerLoginErr" style="min-height:16px;"></div>
        <button class="btn" id="ownerLoginSubmit">${esc(t(isCreate ? "create_account" : "log_in"))}</button>
        ${isCreate ? "" : `<button type="button" class="btn ghost small" id="ownerForgotBtn">${esc(t("forgot_password"))}</button>`}
        <button class="btn ghost small" id="ownerLoginClose">${esc(t("cancel"))}</button>
      </div>
    </div>`;
  modal.style.display = "flex";
  fillGoogleButton(document.getElementById("accGoogle"));
  modal.querySelectorAll("[data-accmode]").forEach((b) => b.addEventListener("click", () => openAccountModal(b.dataset.accmode)));
  document.getElementById("ownerLoginClose").addEventListener("click", () => { modal.style.display = "none"; });
  const errEl = document.getElementById("ownerLoginErr");
  const emailEl = document.getElementById("ownerLoginEmail");
  const forgot = document.getElementById("ownerForgotBtn");
  if (forgot) forgot.addEventListener("click", async () => {
    const email = emailEl.value.trim();
    if (!email) { errEl.textContent = t("enter_email_first"); return; }
    const { error } = await supabaseClient.auth.resetPasswordForEmail(email, { redirectTo: location.href.split("#")[0] });
    errEl.style.color = error ? "" : "var(--good)";
    errEl.textContent = error ? error.message : t("reset_sent");
  });
  document.getElementById("ownerLoginSubmit").addEventListener("click", async () => {
    const email = emailEl.value.trim();
    const password = document.getElementById("ownerLoginPassword").value;
    errEl.style.color = "";
    errEl.textContent = "";
    if (!email || !password) { errEl.textContent = t("enter_both"); return; }
    if (isCreate && password.length < PASSWORD_MIN) { errEl.textContent = t("password_short"); return; }
    try {
      if (isCreate) {
        const anon = CURRENT_SESSION && CURRENT_SESSION.user && CURRENT_SESSION.user.is_anonymous;
        if (anon) {
          // Upgrade the anonymous account: same user id, all saved progress kept.
          const { data, error } = await supabaseClient.auth.updateUser({ email, password, data: { lang: LANG } });
          if (error) { errEl.textContent = friendlyAuthError(error); return; }
          const pending = data && data.user && (data.user.new_email || !data.user.email_confirmed_at);
          if (pending) { errEl.style.color = "var(--good)"; errEl.textContent = t("confirm_email_sent"); return; }
        } else {
          const { data, error } = await supabaseClient.auth.signUp({ email, password, options: { data: { lang: LANG } } });
          if (error) { errEl.textContent = friendlyAuthError(error); return; }
          if (!data.session) { errEl.style.color = "var(--good)"; errEl.textContent = t("confirm_email_sent"); return; }
        }
      } else {
        const { error } = await supabaseClient.auth.signInWithPassword({ email, password });
        if (error) { errEl.textContent = friendlyAuthError(error); return; }
      }
      // Reload so every page reads the account's own saved progress.
      location.hash = "";
      location.reload();
    } catch (err) {
      errEl.textContent = err.message || t("login_failed");
    }
  });
}
// Account emails (confirm, reset password) come in the language used on the
// site: it is kept on the account (user_metadata.lang), which the Supabase
// email templates read (ar / ko, anything else English). Set at sign-up,
// on each start and when the language is changed.
function syncAccountLang() {
  const u = CURRENT_SESSION && CURRENT_SESSION.user;
  if (!u || u.is_anonymous || !u.email || (u.user_metadata || {}).lang === LANG) return;
  supabaseClient.auth.updateUser({ data: { lang: LANG } }).catch(() => {});
}
// Sign in with Google (shown only once Google is switched on in Supabase →
// Authentication → Providers; /auth/v1/settings says so). A guest links Google
// to the account they already have (linkIdentity: same user id, everything
// saved in this browser is kept); if that Google account already has its own
// account (or linking is off), it signs in to that one instead.
const PASSWORD_MIN = 6;
let AUTH_SETTINGS_P = null;
function authSettings() {
  return AUTH_SETTINGS_P || (AUTH_SETTINGS_P = fetch(`${SUPABASE_URL}/auth/v1/settings`, { headers: { apikey: SUPABASE_KEY } })
    .then((r) => (r.ok ? r.json() : {})).catch(() => { AUTH_SETTINGS_P = null; return {}; }));
}
const GOOGLE_G = `<svg viewBox="0 0 48 48" width="18" height="18" aria-hidden="true"><path fill="#FFC107" d="M43.6 20.5H42V20H24v8h11.3C33.7 32.7 29.2 36 24 36c-6.6 0-12-5.4-12-12s5.4-12 12-12c3.1 0 5.8 1.2 7.9 3.1l5.7-5.7C34 6.1 29.3 4 24 4 12.9 4 4 12.9 4 24s8.9 20 20 20 20-8.9 20-20c0-1.3-.1-2.4-.4-3.5z"/><path fill="#FF3D00" d="M6.3 14.7l6.6 4.8C14.7 15.1 19 12 24 12c3.1 0 5.8 1.2 7.9 3.1l5.7-5.7C34 6.1 29.3 4 24 4 16.3 4 9.7 8.3 6.3 14.7z"/><path fill="#4CAF50" d="M24 44c5.2 0 9.9-2 13.4-5.2l-6.2-5.2C29.2 35.1 26.7 36 24 36c-5.2 0-9.6-3.3-11.3-7.9l-6.5 5C9.5 39.6 16.2 44 24 44z"/><path fill="#1976D2" d="M43.6 20.5H42V20H24v8h11.3c-.8 2.2-2.2 4.2-4.1 5.6l6.2 5.2C37 39.2 44 34 44 24c0-1.3-.1-2.4-.4-3.5z"/></svg>`;
async function fillGoogleButton(host) {
  if (!host) return;
  const st = await authSettings();
  if (!(st && st.external && st.external.google) || !host.isConnected) return;
  host.innerHTML = `<button type="button" class="btn ghost acc-google" data-accgoogle>${GOOGLE_G}<span>${esc(t("google_continue"))}</span></button>
    <div class="acc-or"><span>${esc(t("or_email"))}</span></div>`;
  host.querySelector("[data-accgoogle]").addEventListener("click", () => googleSignIn(host));
}
async function googleSignIn(host) {
  const redirectTo = location.href.split("#")[0];
  const btn = host && host.querySelector("[data-accgoogle]");
  if (btn) btn.disabled = true;
  const anon = CURRENT_SESSION && CURRENT_SESSION.user && CURRENT_SESSION.user.is_anonymous;
  if (anon && supabaseClient.auth.linkIdentity) {
    try { sessionStorage.setItem("google_link", "1"); } catch (e) {}
    const { error } = await supabaseClient.auth.linkIdentity({ provider: "google", options: { redirectTo } });
    if (!error) return; // the browser goes to Google
  }
  try { sessionStorage.removeItem("google_link"); } catch (e) {}
  const { error } = await supabaseClient.auth.signInWithOAuth({ provider: "google", options: { redirectTo } });
  if (error) { if (btn) btn.disabled = false; toast(t("google_failed"), true); }
}
// Back from Google with an error. Linking a Google account that already has
// its own account comes back as "identity_already_exists": sign in to it.
function googleReturnCheck() {
  const q = new URLSearchParams(location.search), h = new URLSearchParams(location.hash.replace(/^#/, ""));
  const code = q.get("error_code") || h.get("error_code") || "", desc = q.get("error_description") || h.get("error_description") || "";
  if (!code && !q.get("error") && !h.get("error")) return;
  let linking = false;
  try { linking = sessionStorage.getItem("google_link") === "1"; sessionStorage.removeItem("google_link"); } catch (e) {}
  ["error", "error_code", "error_description"].forEach((k) => q.delete(k));
  history.replaceState(history.state, "", location.pathname + (q.toString() ? "?" + q.toString() : ""));
  if (linking && (code === "identity_already_exists" || /already/i.test(desc))) {
    toast(t("google_in_use"));
    supabaseClient.auth.signInWithOAuth({ provider: "google", options: { redirectTo: location.href.split("#")[0] } });
    return;
  }
  toast(t("google_failed"), true);
}
function friendlyAuthError(error) {
  const m = String(error && error.message || "");
  if (/invalid login|invalid credentials/i.test(m)) return t("invalid_login");
  if (/already registered|already exists|already been registered/i.test(m)) return t("email_taken");
  if (/email not confirmed/i.test(m)) return t("email_not_confirmed");
  if (/rate limit/i.test(m)) return t("rate_limited");
  return m || t("login_failed");
}
// Password reset links land back on the site with a recovery session:
// ask for the new password once, then reload into the account.
supabaseClient.auth.onAuthStateChange((event) => {
  if (event !== "PASSWORD_RECOVERY") return;
  openNewPasswordModal();
});
// The new password is typed in a hidden password box (it used to be a plain
// prompt that showed it on screen), same look as the log-in box.
function openNewPasswordModal() {
  let modal = document.getElementById("newPwModal");
  if (!modal) {
    modal = document.createElement("div");
    modal.id = "newPwModal";
    modal.className = "modal-overlay";
    document.body.appendChild(modal);
  }
  modal.innerHTML = `
    <div class="modal-box" style="max-width:360px;">
      <p class="desc" style="margin:0 0 10px;">${esc(t("new_password_prompt"))}</p>
      <div style="display:flex; flex-direction:column; gap:8px;">
        <input type="password" id="newPwInput" placeholder="${esc(t("password_placeholder"))}" autocomplete="new-password" style="width:100%;" />
        <div class="err" id="newPwErr" style="min-height:16px;"></div>
        <button class="btn" id="newPwSave">${esc(t("save"))}</button>
        <button class="btn ghost small" id="newPwCancel">${esc(t("cancel"))}</button>
      </div>
    </div>`;
  modal.style.display = "flex";
  const input = document.getElementById("newPwInput"), errEl = document.getElementById("newPwErr"), save = document.getElementById("newPwSave");
  document.getElementById("newPwCancel").addEventListener("click", () => { modal.style.display = "none"; });
  const go = async () => {
    const pw = input.value;
    if (!pw) { input.focus(); return; }
    save.disabled = true; errEl.textContent = "";
    const { error } = await supabaseClient.auth.updateUser({ password: pw });
    save.disabled = false;
    if (error) { errEl.textContent = friendlyAuthError(error); return; }
    modal.style.display = "none";
    toast(t("password_updated"));
    location.hash = ""; location.reload();
  };
  save.addEventListener("click", go);
  input.addEventListener("keydown", (e) => { if (e.key === "Enter") go(); });
  setTimeout(() => input.focus(), 50);
}

// App entry point: establish (or restore) a session before anything else
// runs, since every data call needs USER_ID / the session's access token.
// Installable app: the service worker (pwa/sw.js) caches the page and icons
// so the site opens from the home screen and survives a dropped connection.
if ("serviceWorker" in navigator) {
  window.addEventListener("load", () => { navigator.serviceWorker.register("sw.js").catch(() => {}); });
}
function bootLangPack() {
  if (LANG !== "en" && LANG_BUILTIN.some((l) => l.code === LANG && l.file)) loadLangPack(LANG);
}
(async function boot() {
  // A first visit (no saved login) waits about a second for its guest
  // sign-in: the reads that are the same for everyone start now. The pages
  // ask for them again later and share these loads.
  if (!hasSavedLogin()) {
    ensureUiVisibility(); ensureSiteConfig(); bootLangPack();
    if (TAB === "overview") Object.values(dashPublicReads()).forEach((p) => p.catch(() => {}));
  }
  try {
    await ensureAuthSession();
    googleReturnCheck();
    syncAccountLang();
  } catch (err) {
    pageDrawn();
    content.innerHTML = `
      <div class="empty">
        <div class="big">Couldn't start a session</div>
        <p class="desc">${esc(err.message || String(err))}</p>
        <p class="desc">If you're the owner: make sure "Anonymous sign-ins" is enabled in your Supabase project's Authentication settings.</p>
      </div>`;
    return;
  }
  // Speed: start downloading every saved calculator state, the commander
  // name and the category list right away - none of them needs the
  // visibility/site settings below, so they don't wait for them.
  preloadCalcStates();
  // A built-in language's texts load alongside the settings (added languages
  // need the settings first and load in useLanguage below).
  bootLangPack();
  // The Dashboard's fixed reference reads start now, alongside the settings.
  if (TAB === "overview") Object.values(dashFixedReads()).forEach((p) => p.catch(() => {}));
  loadCommander();
  const categoriesLoaded = loadBuffCategories(true);
  await Promise.all([ensureUiVisibility(), ensureSiteConfig()]);
  applyEnglishOverrides(siteConfig("lang_en", null));
  if (LANG !== "en") LANG = await useLanguage(LANG);
  applyGameRules();
  applyMenuLayout();
  renderOwnerLoginUI();
  document.documentElement.dir = langDir(LANG);
  document.documentElement.lang = LANG;
  applyNavLanguage();
  renderLanguageSwitcher();
  startUiLocalizer();
  document.querySelectorAll("button[data-tab]").forEach((x) => {
    x.classList.toggle("active", x.dataset.tab === TAB);
  });
  history.replaceState({ tab: TAB }, "", location.pathname + location.search);
  if (TAB === "overview") {
    // The Dashboard loads what it needs itself, so it doesn't have to wait
    // for the category list first.
    categoriesLoaded.catch(() => {});
    render();
  } else {
    // Render even if the category list failed to load, so the page shows
    // (or shows its own error) instead of staying blank.
    categoriesLoaded.catch(() => {}).then(render);
  }
})();
